int ways(int n) {
    if (n <= 1) return 1;
    return ways(n - 1) + ways(n - 2);
}

int waysMemo(int n) {
    return countWays(n, new Integer[n + 1]);
}

int countWays(int n, Integer[] memo) {
    if (n <= 1) return 1;
    if (memo[n] != null) return memo[n];
    memo[n] = countWays(n - 1, memo) + countWays(n - 2, memo);
    return memo[n];
}

int waysTable(int n) {
    int[] dp = new int[n + 1];
    dp[0] = 1;
    for (int i = 1; i <= n; i++) {
        dp[i] = dp[i - 1];
        if (i >= 2) dp[i] += dp[i - 2];
    }
    return dp[n];
}

